import React, { Component } from "react";
import "./Aboutus.css";

export default class Aboutus extends Component {
    render() {
        return (
           <div>
          <div className="contact-containerr">
                <div className="rectangle"></div>
                <p>TaiLink helps locate lost or stolen pets through the use of a microchip implanted in them. Our website has many features:</p>
                <ul>
                    <li>Enabling them to provide updates via the chip's identification number.</li>
                    <li>Users can also post information about lost pets that have not yet been found or animals in need of assistance.</li>
                    <li>Suggestions for veterinary services or suitable homes can also be provided.</li>
                </ul>
        </div>
        </div>

        );
    }
}
